    30	const authorizationPrefix = "Bearer ";
    31	const authorizationComparisonWidth = 16_391;
    32	
    33	const equalAuthorization = (left: string, right: string) => {
    34	  const leftPadded = left.padEnd(authorizationComparisonWidth, "\0");
    35	  const rightPadded = right.padEnd(authorizationComparisonWidth, "\0");
    36	  let difference = Number(left.length !== right.length);
    37	  for (let index = 0; index < authorizationComparisonWidth; index += 1) {
    38	    difference += Number(
    39	      leftPadded.codePointAt(index) !== rightPadded.codePointAt(index)
    40	    );
    41	  }
    42	  return difference === 0;
    43	};
