    45	export const makeOpenAICompatibleProxy = Effect.fn(
    46	  "OpenAICompatibleProxy.make"
    47	)(function* (internalToken: OpenAICompatibleProxyInternalToken) {
    48	  const directProvider = yield* CodexDirectProvider;
    49	  const expectedAuthorization = `${authorizationPrefix}${Redacted.value(
    50	    internalToken
    51	  )}`;
    52	
    53	  return OpenAICompatibleProxy.of({
    54	    handleChatCompletions: Effect.fn(
    55	      "OpenAICompatibleProxy.handleChatCompletions"
    56	    )(function* (input: OpenAICompatibleProxyInput) {
    57	      if (
    58	        input.authorization === undefined ||
    59	        !equalAuthorization(
    60	          Redacted.value(input.authorization),
    61	          expectedAuthorization
    62	        )
    63	      ) {
    64	        return yield* new OpenAICompatibleProxyAuthError({
    65	          operation: "handleChatCompletions",
    66	          message: "Codex proxy request is not authorized.",
    67	        });
    68	      }
    69	
    70	      return yield* directProvider.streamChatCompletion(input.completion);
    71	    }),
    72	  });
    73	});
