     1	import {
     2	  context,
     3	  propagation,
     4	  SpanStatusCode,
     5	  trace,
     6	} from "@opentelemetry/api";
     7	
     8	import { codexProxyWebHandler } from "./server.js";
     9	
    10	const VercelRewritePathSearchParam = "path";
    11	const ModelInvocationHeader = "x-bundjil-codex-proxy-model-invocation";
    12	const ProxyTracer = trace.getTracer("bundjil-codex-proxy");
    13	
    14	const traceProxyResponse = (
    15	  response: Response,
    16	  span: ReturnType<typeof ProxyTracer.startSpan>
    17	) => {
    18	  const modelInvocation =
    19	    response.headers.get(ModelInvocationHeader) === "true";
    20	
    21	  span.setAttribute("bundjil.codex-proxy.model_invocation", modelInvocation);
    22	  span.setAttribute("http.response.status_code", response.status);
    23	  span.updateName(
    24	    modelInvocation
    25	      ? "bundjil.codex-proxy.model-invocation"
    26	      : "bundjil.codex-proxy.request"
    27	  );
    28	
    29	  if (response.body === null) {
    30	    if (modelInvocation) {
    31	      span.setAttribute("bundjil.codex-proxy.sse_completed", false);
    32	    }
    33	    span.setStatus({ code: SpanStatusCode.OK });
    34	    span.end();
    35	    return response;
    36	  }
    37	
    38	  let completed = false;
    39	  const complete = () => {
    40	    if (completed) {
    41	      return;
    42	    }
    43	
    44	    completed = true;
    45	    if (modelInvocation) {
    46	      span.setAttribute("bundjil.codex-proxy.sse_completed", true);
    47	    }
    48	    span.setStatus({ code: SpanStatusCode.OK });
    49	    span.end();
    50	  };
    51	  const fail = () => {
    52	    if (completed) {
    53	      return;
    54	    }
    55	
    56	    completed = true;
    57	    if (modelInvocation) {
    58	      span.setAttribute("bundjil.codex-proxy.sse_completed", false);
    59	    }
    60	    span.setStatus({
    61	      code: SpanStatusCode.ERROR,
    62	      message: "The proxy response stream did not complete.",
    63	    });
    64	    span.end();
    65	  };
    66	  const reader = response.body.getReader();
    67	  const body = new ReadableStream<Uint8Array>({
    68	    async cancel() {
    69	      try {
    70	        await reader.cancel();
    71	      } finally {
    72	        fail();
    73	      }
    74	    },
    75	    async pull(controller) {
    76	      try {
    77	        const next = await reader.read();
    78	
    79	        if (next.done) {
    80	          complete();
    81	          controller.close();
    82	          return;
    83	        }
    84	
    85	        controller.enqueue(next.value);
    86	      } catch {
    87	        fail();
    88	        controller.error(new Error("The proxy response stream failed."));
    89	      }
    90	    },
    91	  });
    92	
    93	  return new Response(body, {
    94	    headers: response.headers,
    95	    status: response.status,
    96	    statusText: response.statusText,
    97	  });
    98	};
    99	
   100	export const toCodexProxyVercelRequest = (request: Request) => {
   101	  const url = new URL(request.url);
   102	  const rewrittenPath = url.searchParams.get(VercelRewritePathSearchParam);
   103	
   104	  if (rewrittenPath === null) {
   105	    return request;
   106	  }
   107	
   108	  url.searchParams.delete(VercelRewritePathSearchParam);
   109	  url.pathname = rewrittenPath.startsWith("/")
   110	    ? rewrittenPath
   111	    : `/${rewrittenPath}`;
   112	
   113	  return new Request(url, request);
   114	};
   115	
   116	export const fetchCodexProxyVercelRequest = (request: Request) => {
   117	  const parent = propagation.extract(context.active(), request.headers);
   118	
   119	  return context.with(parent, async () => {
   120	    const span = ProxyTracer.startSpan("bundjil.codex-proxy.request");
   121	
   122	    try {
   123	      return traceProxyResponse(
   124	        await codexProxyWebHandler.handler(toCodexProxyVercelRequest(request)),
   125	        span
   126	      );
   127	    } catch (error) {
   128	      span.setAttribute("bundjil.codex-proxy.sse_completed", false);
   129	      span.setStatus({
   130	        code: SpanStatusCode.ERROR,
   131	        message: "The proxy request failed.",
   132	      });
   133	      span.end();
   134	      throw error;
   135	    }
   136	  });
   137	};

